function translateAdminExact(lang){const forward=ADMIN_EN,reverse=Object.fromEntries(Object.entries(forward).map(([a,b])=>[b,a]));const map=lang==='en'?forward:reverse;const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const n of nodes){if(n.parentElement?.closest('pre'))continue;const raw=n.textContent,trimmed=raw.trim();if(trimmed&&map[trimmed])n.textContent=raw.replace(trimmed,map[trimmed])}}
function applyAdminLanguage(lang=adminLang()){localStorage.setItem('par-ui-language',lang);document.documentElement.lang=lang;const brand=lang==='en'?'Personal Agent':'Р РѕРґРЅРѕР№ РђРіРµРЅС‚';$('#adminBrandName').textContent=brand;$('#adminBrandEdition').textContent=lang==='en'?'Administration':'РђРґРјРёРЅРёСЃС‚СЂРёСЂРѕРІР°РЅРёРµ';if($('#adminLoginEyebrow'))$('#adminLoginEyebrow').textContent=lang==='en'?'PERSONAL AGENT':'Р РѕРґРЅРѕР№ РђРіРµРЅС‚';if($('#adminTopEyebrow'))$('#adminTopEyebrow').textContent=lang==='en'?'PERSONAL AGENT':'Р РѕРґРЅРѕР№ РђРіРµРЅС‚';document.title=(lang==='en'?'Administration':'РђРґРјРёРЅРёСЃС‚СЂРёСЂРѕРІР°РЅРёРµ')+' вЂ” '+brand;translateAdminExact(lang);const toggle=$('#adminLocaleToggle');if(toggle)toggle.textContent=lang==='en'?'RU':'EN'}
