async function api(path,options={}){const headers={...(options.headers||{})};const method=String(options.method||'GET').toUpperCase();if(options.body)headers['Content-Type']='application/json';if(token)headers.Authorization='Bearer '+token;if(!token&&!['GET','HEAD','OPTIONS'].includes(method)&&csrfToken)headers['X-CSRF-Token']=csrfToken;const response=await fetch(path,{...options,headers});let payload={};try{payload=await response.json()}catch(_){}if(!response.ok){const error=new Error(payload.error||'РћС€РёР±РєР° Р·Р°РїСЂРѕСЃР°');error.status=response.status;throw error}return payload}
