function formatSize(value){if(!value)return adminText('Р Р°Р·РјРµСЂ РЅРµ СѓРєР°Р·Р°РЅ','Size unavailable');const units=['B','KB','MB','GB','TB'];let n=value,i=0;while(n>=1024&&i<units.length-1){n/=1024;i++}return `${n.toFixed(i>1?1:0)} ${units[i]}`}
