function renderModels(){const host=$('#models');clear(host);const models=inventory();$('#modelCount').textContent=String(models.length);$('#metricModels').textContent=String(models.length);if(!models.length){host.append(node('p','muted',adminText('РќРё РѕРґРЅР° РјРѕРґРµР»СЊ РЅРµ РѕР±РЅР°СЂСѓР¶РµРЅР°. РџСЂРѕРІРµСЂСЊС‚Рµ provider connections.','No models discovered. Check provider connections.')));return}for(const model of models){const card=node('article','model-card model-item');const top=node('div','model-card-top');top.append(node('div','model-glyph','AI'),node('span','model-ready',adminText('РћР±РЅР°СЂСѓР¶РµРЅР°','Discovered')));card.append(top,node('strong','model-name',model.display_name),node('div','model-meta',`${model.provider_name} В· ${model.provider_type}`),node('div','model-meta',formatSize(Number(model.size||0))));host.append(card)}const pull=$('#pullProvider');clear(pull);for(const p of status.providers||[]){if(p.type!=='ollama'||!p.enabled)continue;const o=document.createElement('option');o.value=p.id;o.textContent=p.name;pull.append(o)}}
function renderRoutes(){const routes=$('#routes');clear(routes);const items=inventory();for(const [mode,current] of Object.entries(status.routing||{})){const card=node('div','route-card');const copy=node('div','route-copy');copy.append(node('strong','',routeLabel(mode)),node('small','',adminLang()==='en'?(mode==='auto'?'Balance of quality and speed':mode==='fast'?'Short everyday tasks':'Deeper response'):(mode==='auto'?'Р‘Р°Р»Р°РЅСЃ РєР°С‡РµСЃС‚РІР° Рё СЃРєРѕСЂРѕСЃС‚Рё':mode==='fast'?'РљРѕСЂРѕС‚РєРёРµ РїРѕРІСЃРµРґРЅРµРІРЅС‹Рµ Р·Р°РґР°С‡Рё':'Р‘РѕР»РµРµ РіР»СѓР±РѕРєРёР№ РѕС‚РІРµС‚')));const select=document.createElement('select');select.dataset.mode=mode;for(const item of items){const option=document.createElement('option');option.value=routeValue(item);option.textContent=`[${item.provider_name}] ${item.display_name}`;if(item.provider_id===current.provider_id&&item.model_id===current.model_id)option.selected=true;select.append(option)}if(current&&!items.some(i=>i.provider_id===current.provider_id&&i.model_id===current.model_id)){const option=document.createElement('option');option.value=`${current.provider_id}\u0000${current.model_id}`;option.textContent=`${adminText('[РЅРµРґРѕСЃС‚СѓРїРЅРѕ]','[unavailable]')} ${current.provider_id} / ${current.model_id}`;option.selected=true;select.append(option)}card.append(copy,select);routes.append(card)}}
