function renderVpnRouting(){
const cfg=vpnRoutingStatus?.vpn_routing||{};
const plan=vpnRoutingPlan?.vpn_plan||{};
const enabled=!!cfg.enabled;
const vps1=cfg.vps1||{};
const vps2=cfg.vps2||{};
const upstream=cfg.upstream||{};
if($('#vpnRoutingEnabled'))$('#vpnRoutingEnabled').value=enabled?'1':'0';
if($('#vpnRoutingMode'))$('#vpnRoutingMode').value=cfg.mode||'wireguard';
if($('#vpnPreferenceId'))$('#vpnPreferenceId').value=cfg.preference_id||'';
if($('#vpnVps2Host'))$('#vpnVps2Host').value=vps2.host||'';
if($('#vpnEndpointPort'))$('#vpnEndpointPort').value=String(vps2.endpoint_port||51820);
if($('#vpnNatInterface'))$('#vpnNatInterface').value=vps2.nat_interface||'eth0';
if($('#vpnUpstreamHost'))$('#vpnUpstreamHost').value=upstream.host||'api.example.com';
if($('#vpnUpstreamIp'))$('#vpnUpstreamIp').value=upstream.ip||'';
if($('#vpnAllowedIps'))$('#vpnAllowedIps').value=(upstream.allowed_ips||[]).join('\n');
if($('#vpnInterface'))$('#vpnInterface').value=vps1.interface||'wg0';
if($('#vpnAddress'))$('#vpnAddress').value=vps1.vpn_address||'10.10.0.2/24';
if($('#vpnSubnet'))$('#vpnSubnet').value=vps1.vpn_subnet||'10.10.0.0/24';
if($('#vpnAutostart'))$('#vpnAutostart').value=vps1.autostart?'1':'0';
if($('#vpnNotes'))$('#vpnNotes').value=cfg.notes||'';
const summary=$('#vpnRoutingSummary');
if(summary)summary.textContent=JSON.stringify({enabled:cfg.enabled,mode:cfg.mode,preference_id:cfg.preference_id,service_role:cfg.service_role,vps1:vps1,vps2:vps2,upstream:upstream,plan:!!plan.client_config},null,2);
const instructions=$('#vpnRoutingInstructions');
if(instructions){
const allowed=(upstream.allowed_ips||[]).length?(upstream.allowed_ips||[]).join('\n'):(upstream.ip?`${upstream.ip}/32`:'203.0.113.50/32');
const base=[`# ${cfg.mode==='amneziawg'?'AmneziaWG':'WireGuard'} route for VPS1 -> VPS2`,`# preferenceId: ${cfg.preference_id||'-'}`,''];
if(plan.client_config){
  instructions.textContent=[...base,plan.client_config,'',`# VPS2 server-side requirements`,...(plan.server_commands||[]),'',`# route check`,plan.verification?.route_check||`ip route get ${upstream.ip||'203.0.113.50'}`,'',`# client AllowedIPs`,`AllowedIPs = ${allowed}`,'',`# API verification`,plan.verification?.api_check||`curl https://${upstream.host||'api.example.com'}/v1/models -H "Authorization: Bearer $API_KEY"`].join('\n');
} else {
  instructions.textContent=[...base,`# VPS1 keeps direct traffic; only these destinations go via VPN:`,allowed,'',`# VPS2 server-side requirements`,`sudo sysctl -w net.ipv4.ip_forward=1`,`sudo iptables -t nat -A POSTROUTING -s ${vps1.vpn_subnet||'10.10.0.0/24'} -o ${vps2.nat_interface||'eth0'} -j MASQUERADE`,`sudo systemctl enable wg-quick@${vps1.interface||'wg0'}`,'',`# route check`,`ip route get ${upstream.ip||'203.0.113.50'}`,'',`# client AllowedIPs`,`AllowedIPs = ${allowed}`,'',`# API verification`,`curl https://${upstream.host||'api.example.com'}/v1/models -H "Authorization: Bearer $API_KEY"`].join('\n');
}
}}
