async function refreshLogs(){const out=$('#adminLogs'),audit=$('#adminAudit');if(!out)return;out.textContent=adminText('Р—Р°РіСЂСѓР·РєР°вЂ¦','LoadingвЂ¦');if(audit)audit.textContent=adminText('Р—Р°РіСЂСѓР·РєР°вЂ¦','LoadingвЂ¦');try{const params=new URLSearchParams({limit:'250'});const level=$('#logLevel')?.value||'',event=$('#logEvent')?.value.trim()||'',requestId=$('#logRequest')?.value.trim()||'',correlationId=$('#logCorrelation')?.value.trim()||'';if(level)params.set('level',level);if(event)params.set('event',event);if(requestId)params.set('request_id',requestId);if(correlationId)params.set('correlation_id',correlationId);const payload=await api('/api/admin/logs?'+params);out.textContent=(payload.events||[]).map(item=>`${item.timestamp||''} ${item.level||''} ${item.event||''} req=${item.request_id||'-'} corr=${item.correlation_id||'-'} ${item.status||''}`).join('\n')||adminText('РЎРѕР±С‹С‚РёР№ РїРѕ С„РёР»СЊС‚СЂСѓ РЅРµС‚.','No events match the filter.');if(audit){const auditPayload=await api('/api/admin/audit?limit=100'+(event?'&action='+encodeURIComponent(event):''));audit.textContent=(auditPayload.events||[]).map(item=>`${new Date(Number(item.created_at||0)*1000).toLocaleString('ru-RU')} ${item.action} ${JSON.stringify(item.details)}`).join('\n')||adminText('Audit-СЃРѕР±С‹С‚РёР№ РЅРµС‚.','No audit events.')}}catch(error){out.textContent=error.message;if(audit)audit.textContent=error.message}}
