async function downloadDiagnostics(){const headers={};if(token)headers.Authorization='Bearer '+token;const response=await fetch('/api/admin/diagnostics/download',{headers,credentials:'same-origin'});if(!response.ok)throw new Error((await response.json().catch(()=>({}))).error||'РќРµ СѓРґР°Р»РѕСЃСЊ СЃРѕР±СЂР°С‚СЊ РґРёР°РіРЅРѕСЃС‚РёРєСѓ');const blob=await response.blob();const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`personal-agent-diagnostics-${status.version||'current'}.zip`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),5000)}

