function configureProviderForm(){const preset=$('#providerPreset')?.value||'';const type=$('#providerType')?.value;if(preset==='openai_chatgpt'){if(!$('#providerName').value.trim())$('#providerName').value='OpenAI API';if($('#providerType'))$('#providerType').value='openai_responses';if($('#providerUrl'))$('#providerUrl').value='https://api.openai.com/v1';if($('#providerBillingClass'))$('#providerBillingClass').value='PLATFORM_REMOTE'}else if(preset==='gemini'){if(!$('#providerName').value.trim())$('#providerName').value='Gemini API';if($('#providerType'))$('#providerType').value='openai_compatible';if($('#providerUrl'))$('#providerUrl').value='https://generativelanguage.googleapis.com/v1beta/openai/';if($('#providerBillingClass'))$('#providerBillingClass').value='PLATFORM_REMOTE'}else if(preset==='anthropic'){if(!$('#providerName').value.trim())$('#providerName').value='Anthropic gateway';if($('#providerType'))$('#providerType').value='openai_compatible';if($('#providerUrl'))$('#providerUrl').value='https://api.anthropic.com/v1';if($('#providerBillingClass'))$('#providerBillingClass').value='PLATFORM_REMOTE'}else if(preset==='openrouter'){if(!$('#providerName').value.trim())$('#providerName').value='OpenRouter';if($('#providerType'))$('#providerType').value='openai_compatible';if($('#providerUrl'))$('#providerUrl').value='https://openrouter.ai/api/v1';if($('#providerBillingClass'))$('#providerBillingClass').value='PLATFORM_REMOTE'}else if(preset==='ollama'){if(!$('#providerName').value.trim())$('#providerName').value='Local Ollama';if($('#providerType'))$('#providerType').value='ollama';if($('#providerUrl'))$('#providerUrl').value='http://ollama:11434';if($('#providerBillingClass'))$('#providerBillingClass').value='BYOK'}if(type==='openai_responses'){if(!$('#providerName').value.trim())$('#providerName').value='OpenAI API';if(!$('#providerUrl').value.trim()||$('#providerUrl').value.includes('host.docker.internal'))$('#providerUrl').value='https://api.openai.com/v1';$('#providerBillingClass').value='PLATFORM_REMOTE'}else if(type==='ollama'){if(!$('#providerUrl').value.trim()||$('#providerUrl').value.includes('api.openai.com'))$('#providerUrl').value='http://ollama:11434';$('#providerBillingClass').value='BYOK'}else if(type==='openai_compatible'&&$('#providerUrl').value.includes('api.openai.com')){$('#providerUrl').value=''}}function renderAll(){renderProviders();renderModels();renderRoutes();renderSearchPolicy();renderSiteProfiles();renderUsers();renderBilling();renderDeployments();renderMonitoring();renderSystem()}
